SELECT COUNT(*)
FROM trip
WHERE content_id = #{contentId}

SELECT trip_id AS tripId, content_id AS contentId, name, category, full_address AS fullAddress, image_url AS imageUrl, detail_image_url AS detailImageUrl, lat, lon, region_code AS regionCode, content_type_id AS contentTypeId, tel, homepage, description FROM trip WHERE 1 = 1
AND ( name LIKE CONCAT('%', #{keyword}, '%') OR full_address LIKE CONCAT('%', #{keyword}, '%') )
AND category = #{category}
ORDER BY trip_id DESC LIMIT #{limit} OFFSET #{offset}

